<?php
/**
 * Turns Theme Options into styles.
 *
 * Colors, typography and layout are merged into theme.json (theme origin) via
 * `wp_theme_json_data_theme`, so they apply on the front end and in the block
 * editor. Header/footer colors and a few layout values become CSS custom
 * properties used by assets/theme.css.
 *
 * Generated by DEVOUR.
 */

if (!defined('ABSPATH')) {
	exit;
}

final class WPM_Styles {

	public static function boot() {
		add_filter('wp_theme_json_data_theme', [__CLASS__, 'filter_theme_json']);
		add_action('enqueue_block_assets', [__CLASS__, 'enqueue_fonts']);
		add_action('wp_enqueue_scripts', [__CLASS__, 'enqueue_front']);
		add_filter('wp_resource_hints', [__CLASS__, 'resource_hints'], 10, 2);
	}

	/* ------------------------------------------------------------ helpers */

	private static function font_var($slug) {
		return $slug === '' ? null : 'var(--wp--preset--font-family--' . $slug . ')';
	}

	private static function color($hex, $fallback_slug) {
		return $hex !== '' ? $hex : 'var(--wp--preset--color--' . $fallback_slug . ')';
	}

	/** Drop empty values so theme.json keeps inheriting. */
	private static function compact(array $values) {
		return array_filter($values, function ($v) {
			return $v !== null && $v !== '';
		});
	}

	/* ---------------------------------------------------------- theme.json */

	public static function theme_json_data() {
		$o = WPM_Options::all();
		$c = $o['colors'];
		$t = $o['typography'];
		$l = $o['layout'];

		$palette = [];
		$names   = [
			'base' => 'Background', 'contrast' => 'Text', 'muted' => 'Secondary text',
			'accent' => 'Primary', 'surface' => 'Subtle background', 'border' => 'Border',
		];
		foreach ($names as $slug => $name) {
			$palette[] = ['slug' => $slug, 'name' => $name, 'color' => $c['palette'][$slug]];
		}

		$families = [];
		foreach (WPM_Options::fonts() as $slug => $font) {
			$families[] = ['slug' => $slug, 'name' => $font[0], 'fontFamily' => $font[1]];
		}

		$elements = [
			'link'    => [
				'color'      => ['text' => self::color($c['links']['color'], 'accent')],
				'typography' => ['textDecoration' => $t['links']['decoration']],
				':hover'     => ['color' => ['text' => self::color($c['links']['hover'], 'contrast')]],
			],
			'button'  => [
				'color'      => [
					'background' => self::color($c['buttons']['background'], 'accent'),
					'text'       => $c['buttons']['text'],
				],
				'border'     => ['radius' => $l['corners']['buttons']],
				'typography' => self::compact([
					'fontSize'      => $t['buttons']['size'],
					'fontWeight'    => $t['buttons']['weight'],
					'letterSpacing' => $t['buttons']['letter_spacing'],
					'textTransform' => $t['buttons']['transform'],
				]),
				':hover'     => ['color' => [
					'background' => self::color($c['buttons']['hover_background'], 'contrast'),
					'text'       => $c['buttons']['hover_text'],
				]],
			],
			'heading' => ['typography' => self::compact([
				'fontFamily'    => self::font_var($t['headings']['family']),
				'fontWeight'    => $t['headings']['weight'],
				'lineHeight'    => $t['headings']['line_height'],
				'letterSpacing' => $t['headings']['letter_spacing'],
				'textTransform' => $t['headings']['transform'],
			])],
		];
		foreach (WPM_Options::HEADING_LEVELS as $level) {
			$elements[$level] = ['typography' => self::compact([
				'fontSize'   => $t[$level]['size'],
				'fontWeight' => $t[$level]['weight'],
			])];
		}

		return [
			'version'  => 3,
			'settings' => [
				'color'      => ['palette' => $palette],
				'layout'     => ['contentSize' => $l['widths']['content'], 'wideSize' => $l['widths']['wide']],
				'typography' => ['fontFamilies' => $families],
			],
			'styles'   => [
				'spacing'    => [
					'blockGap' => $l['spacing']['gap'],
					'padding'  => ['left' => $l['spacing']['side'], 'right' => $l['spacing']['side']],
				],
				'typography' => self::compact([
					'fontFamily'    => self::font_var($t['body']['family']),
					'fontSize'      => $t['body']['size'],
					'fontWeight'    => $t['body']['weight'],
					'lineHeight'    => $t['body']['line_height'],
					'letterSpacing' => $t['body']['letter_spacing'],
				]),
				'elements'   => $elements,
				'blocks'     => [
					'core/site-title'          => ['typography' => self::compact([
						'fontFamily'    => self::font_var($t['site_title']['family']),
						'fontSize'      => $t['site_title']['size'],
						'fontWeight'    => $t['site_title']['weight'],
						'letterSpacing' => $t['site_title']['letter_spacing'],
						'textTransform' => $t['site_title']['transform'],
					])],
					'core/navigation'          => ['typography' => self::compact([
						'fontSize'      => $t['navigation']['size'],
						'fontWeight'    => $t['navigation']['weight'],
						'letterSpacing' => $t['navigation']['letter_spacing'],
						'textTransform' => $t['navigation']['transform'],
					])],
					'core/image'               => ['border' => ['radius' => $l['corners']['images']]],
					'core/post-featured-image' => ['border' => ['radius' => $l['corners']['images']]],
				],
			],
		];
	}

	/**
	 * @param WP_Theme_JSON_Data $theme_json
	 */
	public static function filter_theme_json($theme_json) {
		return $theme_json->update_with(self::theme_json_data());
	}

	/* ------------------------------------------------------- CSS variables */

	public static function css_variables() {
		$o = WPM_Options::all();
		$h = $o['colors']['header'];
		$f = $o['colors']['footer'];

		$vars = [
			'--wpm-border'            => 'var(--wp--preset--color--border)',
			'--wpm-header-bg'         => self::color($h['background'], 'base'),
			'--wpm-header-text'       => self::color($h['text'], 'contrast'),
			'--wpm-header-menu'       => $h['menu'] !== '' ? $h['menu'] : 'var(--wpm-header-text)',
			'--wpm-header-menu-hover' => self::color($h['menu_hover'], 'accent'),
			'--wpm-topbar-bg'         => self::color($h['topbar_background'], 'accent'),
			'--wpm-topbar-text'       => $h['topbar_text'],
			'--wpm-footer-bg'         => self::color($f['background'], 'surface'),
			'--wpm-footer-text'       => self::color($f['text'], 'muted'),
			'--wpm-footer-link'       => $f['link'] !== '' ? $f['link'] : 'var(--wpm-footer-text)',
			'--wpm-header-padding'    => $o['header']['general']['padding'],
			'--wpm-logo-width'        => $o['header']['logo']['width'] . 'px',
			'--wpm-section-spacing'   => $o['layout']['spacing']['section'],
			'--wpm-image-radius'      => $o['layout']['corners']['images'],
		];
		$css = ':root{';
		foreach ($vars as $name => $value) {
			$css .= $name . ':' . $value . ';';
		}
		$css .= '}';

		if (WPM_Options::flag('advanced', 'general', 'smooth_scroll')) {
			$css .= '@media (prefers-reduced-motion:no-preference){html{scroll-behavior:smooth}}';
		}
		return $css;
	}

	public static function enqueue_front() {
		$version = WPM_Options::version();
		wp_enqueue_style('wpm-theme', WPM_Options::asset_url('assets/theme.css'), [], WPM_Options::asset_version('assets/theme.css'));
		wp_add_inline_style('wpm-theme', self::css_variables());

		$custom = WPM_Options::get('advanced', 'css', 'custom');
		if ($custom !== '') {
			wp_register_style('wpm-custom-css', false, ['wpm-theme'], $version);
			wp_enqueue_style('wpm-custom-css');
			wp_add_inline_style('wpm-custom-css', $custom);
		}

		wp_enqueue_script('wpm-theme', WPM_Options::asset_url('assets/theme.js'), [], WPM_Options::asset_version('assets/theme.js'), ['in_footer' => true, 'strategy' => 'defer']);
	}

	/* ----------------------------------------------------------- web fonts */

	private static function google_url($spec) {
		return 'https://fonts.googleapis.com/css2?family=' . str_replace(' ', '+', $spec) . '&display=swap';
	}

	/** Google fonts in use: slug => URL. */
	public static function used_google_fonts() {
		$t     = WPM_Options::all()['typography'];
		$fonts = WPM_Options::fonts();
		$used  = [];
		foreach ([$t['body']['family'], $t['headings']['family'], $t['site_title']['family']] as $slug) {
			if ($slug !== '' && !empty($fonts[$slug][2])) {
				$used[$slug] = self::google_url($fonts[$slug][2]);
			}
		}
		return $used;
	}

	public static function enqueue_fonts() {
		foreach (self::used_google_fonts() as $slug => $url) {
			wp_enqueue_style('wpm-font-' . $slug, $url, [], null);
		}
	}

	public static function resource_hints($urls, $relation) {
		if ($relation === 'preconnect' && self::used_google_fonts()) {
			$urls[] = 'https://fonts.googleapis.com';
			$urls[] = ['href' => 'https://fonts.gstatic.com', 'crossorigin'];
		}
		return $urls;
	}
}
